export const TOPICS = [
  { id: "god", title: "God & reality", short: "God", color: "accent", description: "Existence, reason and the shape of a meaningful universe.", question: "Why is there anything at all?" },
  { id: "jesus", title: "Jesus & resurrection", short: "Jesus", color: "gospels", description: "The identity, death and resurrection at the heart of Christian faith.", question: "Who do you say that I am?" },
  { id: "bible", title: "Bible & reliability", short: "Scripture", color: "history", description: "Manuscripts, canon and the patient work of reading in context.", question: "Can we trust what we are reading?" },
  { id: "doubt", title: "Suffering & doubt", short: "Doubt", color: "poetry", description: "Honest questions about pain, silence and the failures of Christians.", question: "Where is God in the difficult chapters?" },
  { id: "worldviews", title: "Religions & worldviews", short: "Worldviews", color: "prophets", description: "Understand the real differences. Read each tradition's own sources.", question: "What do we share—and where do we differ?" },
  { id: "faith", title: "Faith & witness", short: "Witness", color: "epistles", description: "Grace, conviction and conversations that leave room for a person.", question: "How do we live and share this hope?" },
] as const;
export type TopicId = typeof TOPICS[number]["id"];
export interface ApSource { id: string; title: string; author: string; kind: string; url: string; note: string }
export const SOURCES: ApSource[] = [
  { id: "creed", title: "The Nicene Creed", author: "Historic Christian confession · Church of England text", kind: "Confession", url: "https://www.churchofengland.org/faith-life/what-we-believe/nicene-creed", note: "A historic confession of Christian belief. It identifies the doctrine being defended; it is not independent historical evidence for every claim." },
  { id: "aquinas", title: "Summa Theologiae I, question 2", author: "Thomas Aquinas · New Advent edition", kind: "Primary argument", url: "https://www.newadvent.org/summa/1002.htm", note: "Read the objections as well as the replies. Aquinas argues from effects to God; our contingency outline is an introductory reconstruction, not a quotation of his Five Ways." },
  { id: "sinaiticus", title: "Codex Sinaiticus: the manuscript", author: "Codex Sinaiticus Project", kind: "Manuscript", url: "https://codexsinaiticus.org/en/codex/", note: "The project's introduction dates the Greek manuscript to the middle of the fourth century and describes its corrections. Follow its manuscript viewer to inspect the witness itself." },
  { id: "athanasius", title: "Festal Letter 39", author: "Athanasius of Alexandria · New Advent edition", kind: "Historical text", url: "https://www.newadvent.org/fathers/2806039.htm", note: "A historical witness to the books Athanasius received, including the 27 books of the New Testament. One bishop's list is evidence within a wider history of reception." },
  { id: "q112", title: "Qur’an 112:1–4", author: "Qur’an · Quran.com translations", kind: "Religious text", url: "https://quran.com/al-ikhlas", note: "An Islamic primary text on God's oneness and incomparability. Compare translations and commentary; an English rendering is not the Arabic text itself." },
  { id: "q4171", title: "Qur’an 4:171", author: "Qur’an · Quran.com translations", kind: "Religious text", url: "https://quran.com/en/an-nisa/171", note: "A primary passage addressing Jesus and the language of three. Read its whole statement rather than an isolated phrase." },
  { id: "q4157", title: "Qur’an 4:157–158", author: "Qur’an · Quran.com translations", kind: "Religious text", url: "https://quran.com/en/an-nisa/157", note: "Start at 4:157 and continue to 4:158. Distinguish the wording from later explanations of the crucifixion." },
  { id: "humanism", title: "Declaration of Modern Humanism", author: "Humanists International · 2022", kind: "Worldview statement", url: "https://humanists.international/policy/declaration-of-modern-humanism/", note: "An organization's own account of humanist ethics, reason and meaning. It does not speak for every atheist or secular person." },
  { id: "craig-hitchens", title: "Does God Exist? — full transcript", author: "William Lane Craig & Christopher Hitchens · hosted by Reasonable Faith", kind: "Debate transcript", url: "https://www.reasonablefaith.org/media/debates/does-god-exist/", note: "Hosted by Craig's organization, with both speakers' contributions. Read the complete exchange and distinguish a speaker's assertion from demonstrated evidence." },
  { id: "craig-ally-resurrection", title: "Hoax or History? — full transcript", author: "William Lane Craig & Shabir Ally · hosted by Reasonable Faith", kind: "Debate transcript", url: "https://www.reasonablefaith.org/media/debates/hoax-or-history-did-jesus-rise-from-the-dead1/", note: "McGill University, February 2009. The transcript preserves the exchange; the questions in our study guide are editorial prompts, not quotations from the speakers." },
  { id: "craig-ally-god", title: "The Concept of God — full transcript", author: "William Lane Craig & Shabir Ally · hosted by Reasonable Faith", kind: "Debate transcript", url: "https://www.reasonablefaith.org/media/debates/the-concept-of-god-in-islam-and-christianity/", note: "McMaster University, March 2002. A Christian–Muslim exchange about the concept of God; neither speaker represents every member of his tradition." },
];
export interface ApStudy {
  id: string; title: string; topic: TopicId; summary: string; answer: string;
  reasoning: string[]; conclusion: string; sections: { title: string; body: string }[];
  objection: string; reply: string; limit: string; prompt: string;
  refs: { span: Span; note: string }[]; sources: string[]; related: string[]; keywords: string[];
}
const foundationTopics: Record<string, TopicId> = { god: "faith", jesus: "jesus", cross: "jesus", resurrection: "jesus", scripture: "bible", grace: "faith" };
const foundationDepth: Record<string, Pick<ApStudy, "reasoning" | "conclusion" | "sections" | "limit" | "related">> = {
  god: { reasoning: ["The biblical confession is that God is one.", "The New Testament speaks of the Father, Son and Spirit in ways Christian doctrine must hold together.", "The Trinity distinguishes persons while confessing one divine being."], conclusion: "The doctrine claims unity of being and distinction of persons, not three gods or one person wearing three masks.", sections: [{ title: "Define the claim before judging it", body: "A contradiction asserts and denies the same thing in the same respect. Trinitarian language does not say God is one person and three persons. That distinction removes a simple numerical objection; it does not settle every philosophical question about personhood. Read John 1 alongside Matthew 28 and Deuteronomy 6 rather than allowing one illustration to define the doctrine." }, { title: "Why the distinction matters", body: "Christian prayer and salvation are described in relation to the Father, through the Son, in the Spirit. The confession is not a puzzle appended to the gospel: it seeks to make sense of the identity of the one Christians worship. Water, an egg or a three-leaf clover can each suggest a misleading picture. Define what an analogy leaves out before using it." }], limit: "A coherent definition does not by itself prove that God is triune. The scriptural and theological case still needs examination.", related: ["jesus", "islam-trinity", "why-anything"] },
  jesus: { reasoning: ["The Gospel of John attributes divine identity to the Word and identifies the Word with the incarnate Jesus.", "Thomas's confession belongs to the Gospel's stated purpose of bringing readers to faith.", "Assessing Christianity requires examining that claim and the testimony behind it."], conclusion: "The Christian claim is stronger than admiration for a moral teacher: Jesus is the incarnate Son.", sections: [{ title: "Read a whole scene", body: "John 20 places Thomas's confession after his doubts and an encounter with the risen Jesus. Notice what the narrator says, what Thomas says and how Jesus responds. These are distinct pieces of a literary argument. A verse detached from that setting is easier to dismiss and easier to misuse." }, { title: "From a text to a historical judgment", body: "Establishing that John presents Jesus as divine is a textual observation. Establishing that the presentation is true requires further historical and theological reasoning. Ask about the source's purpose, access to testimony, relation to the other Gospels and explanatory power. Do not substitute a slogan such as 'liar, lunatic or Lord' for that investigation." }], limit: "A Gospel's claim to be testimony is evidence to examine, not a guarantee that every reader must accept its conclusion.", related: ["resurrection", "scripture", "islam-jesus"] },
  cross: { reasoning: ["Christian Scripture treats sin as a real rupture requiring reconciliation.", "Jesus describes his death as a willing gift, not merely an accident of politics.", "Paul connects the cross with God's love and reconciling action."], conclusion: "The cross is central to the Christian account of how God addresses guilt, estrangement and the cost of forgiveness.", sections: [{ title: "Several biblical images, one saving work", body: "The New Testament speaks of sacrifice, ransom, reconciliation, victory and justification. These images illuminate different aspects of Christ's work. Christian traditions disagree about how to order and explain them. Let an argument name the model it uses instead of presenting one explanatory theory as the only Christian vocabulary." }, { title: "Begin with who acts", body: "Within Christian belief, the Son gives himself willingly and God acts in Christ to reconcile the world. That matters when discussing whether the cross depicts an unrelated innocent person being punished. It also leaves real questions about justice and representation that deserve a careful answer. Read Mark 10:45 and 2 Corinthians 5 together." }], limit: "An analogy about debt or a courtroom cannot capture every biblical image, and it may hide the very objection a listener is raising.", related: ["grace", "resurrection", "islam-cross"] },
  resurrection: { reasoning: ["Paul records the received message of Jesus' death, burial, resurrection and appearances.", "The Gospel narratives present resurrection as more than the survival of Jesus' influence.", "Christian faith explicitly depends on whether Christ was raised."], conclusion: "The resurrection is a claim about what happened to Jesus, with consequences for Christian truth and hope.", sections: [{ title: "Separate the questions", body: "What did the first Christians proclaim? What experiences did they report? What best explains those reports? These questions are related but not interchangeable. First Corinthians 15 supplies Paul's testimony about a received message and appearances. The passage names witnesses; it does not provide us with 500 independently surviving witness statements." }, { title: "Compare explanations fairly", body: "A historical argument must consider the sources, possible dependence between accounts and alternative explanations such as mistaken experiences or developing traditions. The Christian argues that God's raising Jesus makes sense of the evidence and of Jesus' identity. That inference also depends on wider judgments about God and miracles. Make those assumptions visible rather than describing a contested reconstruction as unanimous scholarship." }], limit: "Historical reasoning is not a laboratory repeat of the event. Distinguish confidence in the sources from confidence in a supernatural explanation.", related: ["miracles", "jesus", "islam-cross"] },
  scripture: { reasoning: ["Interpretation asks what a text means; transmission asks how its wording reached us.", "Historical reliability and divine inspiration are further questions requiring their own arguments.", "An objection can be assessed only after we identify which of these claims is at issue."], conclusion: "Trustworthy reading begins with a specific passage and a specific question.", sections: [{ title: "Avoid answering the wrong question", body: "A person asking why translations differ may be asking about Greek vocabulary, not whether God exists. A person troubled by violence may be asking a moral question, not a manuscript question. Define the issue together. Compare the paragraph, its literary form and the wider book before offering a harmonization." }, { title: "Let the text be inspected", body: "Open more than one translation in the reader. Note where the wording differs and ask whether the difference changes the meaning. For a manuscript claim, consult the witness or a critical discussion of that passage. The presence of textual variants is not a secret to hide, and a catalogue of variants alone is not an argument that no wording can be recovered." }], limit: "The Bible's description of inspiration states a Christian conviction; it does not function as an independent proof of that conviction to someone who questions it.", related: ["manuscripts", "canon", "contradictions"] },
  grace: { reasoning: ["Ephesians describes salvation as God's gift rather than a ground for boasting.", "The same paragraph describes a life created for good works.", "Gift and transformation belong together without becoming the same claim."], conclusion: "Good works express the life of grace; they do not turn grace into a wage.", sections: [{ title: "Read the whole paragraph", body: "Stopping at Ephesians 2:9 loses the movement into verse 10. Starting at verse 10 without the preceding gift language loses it in the other direction. The paragraph lets Christians speak of both dependence on God and responsibility for how they live." }, { title: "Make room for real change", body: "A testimony can describe how grace changed a life without claiming the person has become flawless. Repentance includes facing harm, seeking forgiveness and pursuing repair. Christian traditions explain justification, faith and sanctification differently; when those differences matter, identify them rather than flattening all Christians into one formula." }], limit: "A changed life may commend a faith, but it is not a substitute for examining that faith's central truth claims.", related: ["cross", "church-harm", "conversation"] },
};
const core: ApStudy[] = FOUNDATIONS.map((f) => ({ id: f.id, title: f.question, topic: foundationTopics[f.id], summary: f.title, answer: f.claim, ...foundationDepth[f.id], objection: f.question, reply: f.response, prompt: f.ask, refs: f.refs, sources: f.id === "god" || f.id === "jesus" ? ["creed"] : [], keywords: [f.label, "foundation", "Christianity"] }));

export const STUDIES: ApStudy[] = [...core,
  { id: "why-anything", title: "Why is there something rather than nothing?", topic: "god", summary: "Contingency, explanation and what a first cause would actually establish.", answer: "A Christian philosophical case asks whether dependent reality can be its own ultimate explanation. The proposal is a necessary source of being, rather than one more unexplained object inside the universe.", reasoning: ["Many things we encounter depend on conditions beyond themselves.", "An explanation of each dependent thing may leave the existence of dependent reality itself unexplained.", "If dependent reality requires an ultimate explanation, that explanation cannot be merely another dependent member of it."], conclusion: "On those premises, a necessary source is a candidate explanation for contingent existence.", sections: [{ title: "A question deeper than an earlier event", body: "This argument is about dependence, not simply the first moment on a clock. Aquinas's question 2 is a historic starting point for arguments from effects to God. Our outline uses a modern introductory form of contingency reasoning; it should not be confused with a verbatim statement of his Five Ways." }, { title: "Test the disputed premise", body: "A critic may accept that individual things have explanations while denying that reality as a whole needs one. Another may question whether the proposed necessary source explains more than a necessary universe would. State why you think the explanatory demand is justified. The interesting work happens there, not in repeating the conclusion more forcefully." }], objection: "Then who created God?", reply: "The proposed conclusion concerns a necessary, underived source. It does not begin with 'everything has a creator.' The critic can still challenge whether such a source exists or whether the distinction is justified.", limit: "This line of reasoning alone does not establish the Trinity, the incarnation or the resurrection. Those require further arguments.", prompt: "What would count as a satisfying explanation of existence itself?", refs: [{ span: [44017024, 44017028], note: "Paul speaks of God as the giver of life" }], sources: ["aquinas"], related: ["science", "morality", "god"], keywords: ["cosmological", "first cause", "creation", "atheism", "contingency"] },
  { id: "morality", title: "Can we be good without believing in God?", topic: "god", summary: "Separate moral behaviour from the grounding of moral obligation.", answer: "Yes: a person need not believe in God to show generosity, courage or justice. A moral argument for God asks a different question: what makes moral truths and obligations binding, if they are objective?", reasoning: ["People with different worldviews can recognise and practise moral goods.", "Explaining how we learn morality differs from explaining what makes a moral claim true.", "Christian theism proposes God's good character as a ground of moral value; secular accounts offer alternatives."], conclusion: "A useful discussion compares explanations of moral truth instead of questioning the character of unbelievers.", sections: [{ title: "Do not mistake a person for a premise", body: "An atheist's generosity is not an embarrassment for Christianity. Christians understand human dignity and moral awareness as extending beyond the church. Romans 2 describes the work of the law in those without Israel's written law. The philosophical question concerns what accounts for that moral reality." }, { title: "Take the alternatives seriously", body: "A secular moral realist can hold that moral truths are objective without grounding them in God. A humanist can appeal to flourishing and shared responsibility. Ask how an account moves from descriptions of desires or outcomes to obligations. Apply that same scrutiny to your own account rather than assuming that adding the word God resolves every difficulty." }], objection: "Is something good merely because God commands it?", reply: "A common Christian response grounds goodness in God's character and commands in that character, rather than in arbitrary preference. Critics can still ask whether that explains goodness or simply relocates the question.", limit: "Disagreement about moral foundations does not show that an individual lacks morality.", prompt: "Do you think some things would be wrong even if everyone approved of them?", refs: [{ span: [45002014, 45002016], note: "Conscience and moral accountability" }, { span: [33006008, 33006008], note: "Justice, mercy and humility" }], sources: ["humanism"], related: ["why-anything", "secular", "suffering"], keywords: ["ethics", "atheist", "goodness", "Euthyphro", "objective"] },
  { id: "science", title: "Has science made God unnecessary?", topic: "god", summary: "Mechanisms, meaning and the danger of building faith on gaps.", answer: "A scientific account of a process and a theological account of creation can address different explanatory questions. They can also conflict when a religious interpretation makes a testable claim. The task is to identify the actual claim, not to declare automatic harmony or automatic war.", reasoning: ["Science investigates the natural world through models, observation and testing.", "Christian belief in creation concerns the dependence and meaning of that world.", "Whether a particular interpretation conflicts with evidence must be assessed claim by claim."], conclusion: "Explaining a natural mechanism does not by itself decide whether reality has a divine ground or purpose.", sections: [{ title: "Leave room for discovery", body: "If an argument says that God must act wherever science has no present explanation, its force changes whenever an explanation is found. Christian belief in a creator need not compete with every natural cause. Ask whether the argument would survive learning more about how a process works." }, { title: "Name the level of disagreement", body: "Christians differ on the interpretation of Genesis and on the relation between divine action and natural processes. An assertion about the age of a physical object requires evidence appropriate to that assertion. An argument about why there is an intelligible world asks a further philosophical question. Moving between those questions without notice makes both science and theology harder to understand." }], objection: "Is God just an explanation for what we do not know?", reply: "A gap argument can have that weakness. A broader theistic argument asks about the existence, order or intelligibility of the whole natural world, including what is already explained scientifically.", limit: "This distinction does not settle particular disputes in cosmology or biology. Those require the relevant scientific evidence.", prompt: "Which scientific finding do you think conflicts with which Christian claim?", refs: [{ span: [19019001, 19019004], note: "Creation as a witness" }], sources: [], related: ["why-anything", "miracles", "scripture"], keywords: ["evolution", "creation", "cosmology", "big bang", "reason"] },
  { id: "miracles", title: "Can a reasonable person believe in miracles?", topic: "jesus", summary: "Possibility, testimony and the difference between surprising and well-supported.", answer: "A miracle claim should be tested rather than accepted because it is inspiring or dismissed simply by definition. If God exists, divine action is not automatically impossible. That possibility still leaves the work of assessing a particular report.", reasoning: ["An extraordinary claim needs evidence suited to its importance and alternatives.", "The prior plausibility of divine action depends partly on a person's wider worldview.", "A specific report must be assessed for source quality, context and competing explanations."], conclusion: "Possibility is a starting question; the evidence for an actual event is a separate question.", sections: [{ title: "Ask what the report actually says", body: "A statement that someone felt better is not the same as a documented recovery, and neither automatically establishes its cause. For an ancient account, identify the author's claim, genre and sources. For the resurrection, examine the specific testimony rather than treating all unusual stories as interchangeable." }, { title: "Make the comparison explicit", body: "Ask which explanation accounts for the evidence with the fewest unsupported assumptions. Both a naturalistic and a supernatural explanation can be overstated. A Christian need not defend every alleged miracle in order to examine the resurrection seriously, and a skeptic need not prove fraud to withhold judgment on an inadequately supported report." }], objection: "A miracle violates everything we know about regular natural events.", reply: "Regularity explains why the event would be unusual. It does not alone establish whether a creator could act or whether this event occurred. Those require an argument about divine action and an assessment of testimony.", limit: "An unexplained event is not automatically evidence of a miracle, much less of one particular religion.", prompt: "Would you distinguish 'impossible' from 'possible but not yet convincing'?", refs: [{ span: [43020024, 43020031], note: "Thomas, testimony and belief" }], sources: [], related: ["resurrection", "science", "why-anything"], keywords: ["supernatural", "evidence", "testimony", "naturalism"] },
  { id: "manuscripts", title: "Has the Bible been changed beyond recognition?", topic: "bible", summary: "Look at actual witnesses instead of a telephone-game analogy.", answer: "Copying produced differences between manuscripts. Comparing surviving witnesses makes those differences visible and allows reasoned judgments about earlier readings. Neither the existence of variants nor a large manuscript count settles every disputed passage.", reasoning: ["Hand-copied texts can preserve both shared readings and differences.", "Independent witnesses and their relationships can be compared.", "A textual claim should identify the passage, witnesses and significance of the difference."], conclusion: "The question is what the evidence supports for a particular reading, not whether every copy is identical.", sections: [{ title: "Meet a surviving witness", body: "The Codex Sinaiticus Project presents a Greek biblical manuscript from the middle of the fourth century, including the earliest complete Christian New Testament. Its pages also contain corrections. The project makes a concrete witness available for inspection: a better starting point than imagining a single secret chain of copies." }, { title: "Ask a precise question", body: "Which words differ? How early and independent are the witnesses? Does the change affect spelling, wording or a larger passage? How do editors explain their decision? A comparison of versions in this site's reader is useful for identifying a question, but a translation difference need not be a manuscript difference. It may reflect a different translation choice." }], objection: "If there are variants, how can the text be trustworthy?", reply: "Variants show the need for textual criticism. Confidence in a reading depends on the available witnesses and the reasoning used to compare them. Some readings remain disputed; acknowledge those rather than claiming perfect uniformity.", limit: "Recovering wording does not by itself establish the historical truth or divine inspiration of the words recovered.", prompt: "Can we examine one specific changed passage together?", refs: [{ span: [42001001, 42001004], note: "Luke's stated purpose" }], sources: ["sinaiticus"], related: ["scripture", "canon", "contradictions"], keywords: ["corruption", "variants", "telephone", "translation", "textual criticism"] },
  { id: "canon", title: "Who decided which books belong in the Bible?", topic: "bible", summary: "Canon as a history of reception, with documents we can inspect.", answer: "The history of the canon involves communities receiving, using and debating writings over time. A claim that one meeting simply invented the whole Bible needs evidence. So does a claim that every community always used exactly the same list.", reasoning: ["A collection's history can be investigated through surviving lists and usage.", "Athanasius's Festal Letter 39 names the 27 New Testament books familiar today.", "That document is a witness to reception, not a complete history of every Christian community."], conclusion: "Begin with dated witnesses and distinguish the history of recognition from a theological explanation of authority.", sections: [{ title: "Read the list itself", body: "Athanasius distinguishes books included in his canon from other books recommended for reading. That distinction lets us see more than a modern summary could. Ask who is writing, to whom, and how the categories work in the document." }, { title: "Separate Old and New Testament questions", body: "Christian traditions differ over the extent and status of certain Old Testament books. The common 27-book New Testament does not erase those differences. This Bible reader's 66-book arrangement is a practical scope, not proof that the history of Christian canons was simple. Naming the particular collection under discussion prevents an answer from becoming misleading." }], objection: "Did church leaders choose books just to enforce their power?", reply: "Power is a historical question worth examining, but motive alone is not a history. Ask which decision, which sources record it and what evidence exists for reception before and after it.", limit: "A list documents reception; additional reasoning is needed to defend the authority of the books on that list.", prompt: "Are you asking how the books were recognised, or why Christians consider them authoritative?", refs: [{ span: [55003014, 55003017], note: "Scripture and its purpose" }], sources: ["athanasius"], related: ["scripture", "manuscripts", "jesus"], keywords: ["council", "Nicaea", "books", "apocrypha", "authority"] },
  { id: "contradictions", title: "What should we do with apparent Bible contradictions?", topic: "bible", summary: "A method for comparing passages without forcing them to agree.", answer: "Set the exact claims beside each other, read their contexts and ask whether they assert incompatible things in the same respect. Some differences reflect selection or emphasis; others need more historical or textual work.", reasoning: ["Two accounts can include different details without logically contradicting each other.", "A contradiction requires genuinely incompatible claims, not merely missing details.", "A proposed reconciliation must fit the text rather than invent unsupported facts."], conclusion: "Neither a quick charge of contradiction nor an elaborate harmonization should replace close reading.", sections: [{ title: "Use a comparison worksheet", body: "Write down each passage's claim, setting, speaker and purpose. Mark what is explicit and what you are inferring. Then state the alleged conflict in one sentence. This often reveals that the discussion depends on an assumption about chronology, precision or completeness that should itself be examined." }, { title: "Let an unresolved question remain visible", body: "A possible scenario may show that two statements could both be true. That is different from showing that the scenario actually happened. Label that difference. The Gospel harmony in Study opens parallel accounts side by side so a reader can compare the words rather than rely on a paraphrased dispute." }], objection: "Isn't harmonization just making excuses?", reply: "It can be, if it invents details or ignores the wording. But considering genre and complementary perspectives is ordinary interpretation. Judge a proposed explanation by its evidence and assumptions.", limit: "A logically possible solution is not automatically a historically established one.", prompt: "Which two sentences do you believe cannot both be true?", refs: [{ span: [42001001, 42001004], note: "Purpose and orderly narration" }], sources: [], related: ["scripture", "resurrection", "manuscripts"], keywords: ["errors", "inerrancy", "Gospel harmony", "discrepancies"] },
  { id: "suffering", title: "How can a good God allow suffering?", topic: "doubt", summary: "Take the intellectual challenge seriously without turning grief into a debate.", answer: "Christian faith affirms both God's goodness and the reality of evil. It offers reasons that some goods may involve freedom, risk and a stable world, while also bringing lament, the cross and promised restoration into the conversation. It does not give us an explanation for every person's loss.", reasoning: ["Suffering challenges belief in an all-good, all-powerful God.", "Showing that God and some suffering could coexist differs from explaining the amount and kinds of suffering we see.", "The Christian response also asks how God enters suffering in Christ and what hope resurrection offers."], conclusion: "A philosophical response and a compassionate presence serve different needs; a faithful witness may need both.", sections: [{ title: "Two different challenges", body: "A logical objection says that any evil is incompatible with God. An evidential objection argues that the scale or character of suffering makes such a God less plausible. A possible reason for permitting one kind of evil does not answer every instance or the cumulative weight of the problem. Keep the scope of a reply clear." }, { title: "Begin where the person is", body: "John 11 depicts Jesus weeping in the presence of death. The Psalms contain lament rather than a demand to hide distress. When someone speaks about losing a parent, listen before offering a theory. A Christian can confess hope while refusing to claim knowledge of why that particular loss occurred." }], objection: "Free will does not explain disease or natural disasters.", reply: "That is a serious limitation of a simple free-will reply. Other Christian responses discuss a stable natural order and the hope of restoration, but those still face questions about the severity and distribution of suffering.", limit: "Do not tell a grieving person that you know the hidden purpose of their suffering, or imply that enduring harm is a test they must accept.", prompt: "Would it help more to talk through the question, or to have someone listen to what happened?", refs: [{ span: [43011032, 43011036], note: "Jesus weeps" }, { span: [19013001, 19013006], note: "A prayer of lament" }, { span: [66021001, 66021005], note: "The Christian hope of restoration" }], sources: [], related: ["hiddenness", "cross", "resurrection"], keywords: ["evil", "pain", "grief", "death", "loss", "theodicy"] },
  { id: "hiddenness", title: "Why does God seem silent?", topic: "doubt", summary: "Unanswered seeking, honest prayer and the limits of easy explanations.", answer: "The experience of sincerely seeking God without finding clear assurance is a real challenge to belief in a loving God. Christians can point to revelation in Christ and make room for lament while acknowledging that this does not explain every experience of absence.", reasoning: ["A loving God would seem to desire relationship with people.", "Some people report sincere openness yet remain unconvinced or feel abandoned.", "A Christian response must address that experience rather than assume every doubter is resisting."], conclusion: "The question concerns the availability of relationship and evidence, not merely whether someone has tried hard enough.", sections: [{ title: "Distinguish doubt from refusal", body: "A person may have intellectual questions, emotional exhaustion, a history of harmful religious relationships or simply no sense of God's presence. Do not assign a motive before listening. Psalm 13 offers language for the experience of waiting without requiring the speaker to pretend that waiting is easy." }, { title: "Offer an invitation with room to decline", body: "Reading a Gospel together, making time for honest prayer or returning to one specific question can be meaningful next steps. They are invitations, not guaranteed techniques for producing an experience. Christian confidence in God's character should make a conversation more patient, not more dismissive." }], objection: "If God wants relationship, why isn't his existence obvious to every willing person?", reply: "Christians propose reasons connected with freedom, formation and the nature of faith, but none should be used to deny that sincere nonbelief exists. The force of each explanation needs argument, particularly for a person already open to relationship.", limit: "Do not promise a particular feeling or treat continuing uncertainty as proof of moral failure.", prompt: "What would you hope God's presence would look like in your life?", refs: [{ span: [19013001, 19013006], note: "How long?" }, { span: [41009020, 41009024], note: "Faith voiced alongside need" }], sources: [], related: ["suffering", "jesus", "conversation"], keywords: ["silence", "unanswered prayer", "doubt", "nonbelief", "faith"] },
  { id: "church-harm", title: "What about the harm done by Christians?", topic: "doubt", summary: "Truth, accountability and repentance must belong together.", answer: "A Christian answer begins by acknowledging real wrongdoing. The claim that Christians fail to live up to Jesus does not excuse them. It calls for truthfulness, accountability and repair, while leaving a distinct question about whether Jesus' claims are true.", reasoning: ["Christian teaching makes demands on the conduct of Christians.", "Misconduct can contradict that teaching and undermine the credibility of witnesses.", "An honest response must address both the harm and the truth claims, without using one to evade the other."], conclusion: "Defending Christ never requires defending wrongdoing committed in his name.", sections: [{ title: "Do not make a wounded person defend their pain", body: "Ask what happened and what response they need before arguing about generalizations. An institution's reputation is not more important than the truth. Repentance is more than saying that every group has bad members; it includes naming what was wrong and pursuing responsibility." }, { title: "Distinguish an excuse from an argument", body: "It is logically possible for a belief to be true while its adherents behave badly. But that observation does not erase evidence of hypocrisy or answer a person's distrust. Jesus' warnings against religious hypocrisy belong in the Christian answer itself. Ask what living consistently with those warnings would require now." }], objection: "If Christianity changes people, why are some Christians cruel?", reply: "Christian claims about transformation create a legitimate expectation of fruit. Persistent cruelty deserves to be challenged rather than renamed as faithfulness. A fuller discussion can consider repentance, freedom and the difference between professing faith and living it.", limit: "Do not pressure someone to return to an unsafe relationship or institution in order to prove forgiveness or faith.", prompt: "What would a truthful and accountable response to that harm involve?", refs: [{ span: [40023023, 40023028], note: "Jesus confronts hypocrisy" }, { span: [43013034, 43013035], note: "Love as a public mark of discipleship" }], sources: [], related: ["grace", "suffering", "conversation"], keywords: ["hypocrisy", "abuse", "church", "trust", "repentance"] },
  { id: "islam-jesus", title: "Do Christians and Muslims mean the same thing by Jesus?", topic: "worldviews", summary: "Shared vocabulary can conceal very different claims about his identity.", answer: "Christianity and Islam both give Jesus an important place, but they do not make the same claims about him. Historic Christianity confesses the incarnate Son. Qur’an 4:171 presents Jesus as Messiah and messenger while rejecting language central to Christian confession.", reasoning: ["Shared names and titles do not always carry identical meanings.", "John 1 identifies the Word with God and speaks of the Word becoming flesh.", "Qur’an 4:171 speaks about Jesus within an emphatically Islamic account of God's oneness."], conclusion: "The conversation should compare the meaning of the claims, not merely count shared titles.", sections: [{ title: "Read each account on its own terms", body: "Read John 1:1–18 and Qur’an 4:171 in full, using the linked sources. Ask what 'Word,' 'Messiah' and 'Son' mean in the account being discussed. A Christian should not assume that the presence of a familiar title proves the whole Christian doctrine within a different religious text." }, { title: "Move from comparison to evaluation", body: "First explain each position in a way its adherents can recognise. Then ask which account is best supported, what authorities each person accepts and why. The disagreement about Jesus' identity connects naturally to the cross, resurrection and the reliability of the sources used to describe him." }], objection: "Could Jesus be a prophet without being divine?", reply: "That is a coherent alternative claim. The Christian case must explain why the New Testament's stronger identification should be believed, rather than treating agreement that Jesus was a prophet as agreement with Christianity.", limit: "Muslim interpretations vary. One passage or one debater does not exhaust Islamic thought.", prompt: "When you call Jesus Messiah or Word, what do those titles mean to you?", refs: [{ span: [43001001, 43001018], note: "John's prologue" }], sources: ["q4171", "creed"], related: ["jesus", "islam-trinity", "islam-cross"], keywords: ["Muslim", "Islam", "Isa", "prophet", "incarnation"] },
  { id: "islam-trinity", title: "Does the Trinity contradict God's oneness?", topic: "worldviews", summary: "Define tawhid and Trinity before arguing about either.", answer: "Christians confess one God and distinguish Father, Son and Spirit. Islam's account of divine oneness rejects the Christian trinitarian confession. Agreeing that God is one therefore begins the conversation; it does not resolve the disagreement.", reasoning: ["Deuteronomy 6 is foundational to Christian confession of one God.", "Christian trinitarian language distinguishes person and being.", "Qur’an 112 and 4:171 provide primary texts for examining the Islamic objection."], conclusion: "The issue is whether the Christian account of personal distinction within one God is coherent and warranted.", sections: [{ title: "Avoid a biological misunderstanding", body: "Christian language about the eternal Son does not mean God fathered a child through sexual reproduction. The incarnation and eternal sonship are distinct claims. Clearing up that misunderstanding is useful, but a Muslim may understand the Christian position accurately and still reject it." }, { title: "What remains to argue", body: "After definitions are clear, discuss the biblical grounds, the coherence of the doctrine and why each person accepts their religious sources. Do not assume that explaining the Trinity is the same thing as demonstrating it. Nor should a Christian invent contradictions in an opponent's position instead of answering the actual objection." }], objection: "Three persons sounds like three centres of divinity, whatever words Christians use.", reply: "Historic Christian theology denies three independent divine beings. It still owes a careful account of personhood and unity. Begin with the doctrinal distinction and the biblical reasons for making it, then work through the philosophical objection.", limit: "Analogies can easily imply either three gods or one person appearing in three forms. No simple object lesson establishes the doctrine.", prompt: "Is your objection to the definition itself, or to the evidence Christians give for it?", refs: [{ span: [5006004, 5006005], note: "One Lord" }, { span: [40028018, 40028020], note: "Father, Son and Holy Spirit" }], sources: ["q112", "q4171", "creed"], related: ["god", "islam-jesus", "why-anything"], keywords: ["tawhid", "Islam", "Muslim", "three gods", "monotheism"] },
  { id: "islam-cross", title: "Why does the crucifixion divide Christianity and Islam?", topic: "worldviews", summary: "A disagreement about an event, its meaning and the authority of sources.", answer: "The New Testament places Jesus' death and resurrection at the centre of the gospel. Qur’an 4:157 denies that the opponents described there killed or crucified him, and 4:158 speaks of God raising him. How these texts are interpreted is central to the disagreement.", reasoning: ["Paul's received gospel includes Christ's death, burial and resurrection.", "Qur’an 4:157–158 gives a different account of what Jesus' opponents accomplished.", "A discussion must examine both the historical evidence and the authority assigned to revelation."], conclusion: "The disagreement cannot be resolved simply by saying that both traditions honour Jesus.", sections: [{ title: "Text and interpretation", body: "Read the Qur’anic wording before attributing a detailed replacement or survival theory to every Muslim. Explanations of the passage need to be distinguished from the text itself. Read the New Testament testimony with equal care, including the connection between death, burial and resurrection in 1 Corinthians 15." }, { title: "Ask which question is deciding the issue", body: "Is the objection that crucifixion did not happen, that Jesus did not die, that resurrection is impossible, or that a prophet should not suffer such a death? Those are different claims. Ask what evidence could count against the proposed interpretation. The Craig–Ally resurrection exchange offers one concrete discussion to examine, not a proxy for every Muslim position." }], objection: "Would God allow his messenger to suffer a humiliating death?", reply: "Christianity understands the cross as voluntary self-giving vindicated by resurrection. That theological claim should be argued from its sources rather than assumed. The historical question of what happened remains distinct from what a person expects God would allow.", limit: "Do not treat a disputed interpretation of Qur’an 4:157 as a unanimous Muslim position.", prompt: "Is the main obstacle historical evidence, or what you believe God would permit?", refs: [{ span: [46015003, 46015008], note: "Paul's received proclamation" }, { span: [41015033, 41015039], note: "Mark's account of Jesus' death" }], sources: ["q4157"], related: ["cross", "resurrection", "islam-jesus"], keywords: ["Islam", "Muslim", "crucified", "substitution", "death"] },
  { id: "secular", title: "How do we talk with someone who has no religion?", topic: "worldviews", summary: "Start with their actual account of meaning, evidence and a good life.", answer: "A person without a religion may be atheist, agnostic, undecided or simply disengaged from religious institutions. Ask what they believe before choosing an argument. A Christian conversation can explore meaning, moral obligation and Jesus without assuming the other person has no values.", reasoning: ["Not belonging to a religion does not identify a complete worldview.", "Shared concerns about truth, human dignity and suffering can open real questions.", "Christian claims about God and Jesus still require reasons that address the listener's actual objections."], conclusion: "A good conversation is a meeting of people and arguments, not a contest between stereotypes.", sections: [{ title: "Listen to a self-description", body: "Humanists International's 2022 declaration describes a positive humanist commitment to ethics, reason, flourishing and meaning. Reading it is useful preparation for some conversations. It does not license assuming that every atheist subscribes to that declaration." }, { title: "Find a question worth sharing", body: "Ask whether the person is interested in why there is a universe, what grounds morality, what the Gospels claim or something more personal. Begin where there is genuine interest. If they say evidence matters, ask together what kind of evidence a historical or philosophical claim could reasonably have. Both participants should be able to explain what might change their view." }], objection: "Religion is unnecessary; people can build meaningful lives without it.", reply: "Christians can recognise meaning and goodness in others' lives. The further question is whether the Christian claims about God and Christ are true, and how those claims illuminate the meaning people already experience.", limit: "An argument about meaning should not imply that a nonreligious person's life is empty or worthless.", prompt: "What questions about life or belief, if any, do you find yourself returning to?", refs: [{ span: [44017022, 44017028], note: "Paul begins with his hearers' world" }], sources: ["humanism"], related: ["morality", "why-anything", "conversation"], keywords: ["atheism", "agnostic", "humanism", "secular", "meaning"] },
  { id: "conversation", title: "How can conviction and gentleness belong together?", topic: "faith", summary: "A practical pattern: listen, clarify, give a reason, invite.", answer: "First Peter 3 places readiness to answer alongside gentleness and a good conscience. Christian conviction should make the content clear; Christian love should shape how a person is treated throughout the exchange.", reasoning: ["A clear answer requires understanding the question actually being asked.", "The manner of a response can either express or contradict the message.", "An invitation to continue allows thought and relationship to outlast one exchange."], conclusion: "The aim is a truthful, intelligible witness offered to a person with freedom to respond.", sections: [{ title: "Reflect before replying", body: "Summarise the other person's objection and ask whether you understood it. If they correct you, revise your summary. This is not a tactic to lower defences; it is a way of making sure you answer the real question. A strong answer to an objection nobody made is wasted effort." }, { title: "Give one reason well", body: "Explain a single claim, its evidence and its limitations. Open the passage or source instead of relying on a remembered quotation. If you do not know, say what you would need to check. Finish with a possible next step: read a Gospel, examine one source, or return to a question another day." }], objection: "Does being gentle mean avoiding disagreement?", reply: "No. You can name a real disagreement plainly, ask searching questions and defend a conclusion while refusing contempt or pressure. Gentleness concerns how truth is offered, not whether truth matters.", limit: "Listening is not a script for securing a conversion. The other person remains free to disagree or end the conversation.", prompt: "Have I understood your concern, or am I answering a different question?", refs: [{ span: [60003015, 60003016], note: "Readiness and gentleness together" }, { span: [51004005, 51004006], note: "Wisdom and gracious speech" }], sources: [], related: ["grace", "hiddenness", "secular"], keywords: ["evangelism", "ministry", "witness", "dialogue", "listening"] },
];

