export const DEBATES = [
  { id: "craig-hitchens", title: "Does God exist?", speakers: "William Lane Craig · Christopher Hitchens", setting: "Biola University · April 2009", source: "craig-hitchens", lens: "Theism & atheism", description: "Compare arguments for God's existence with challenges to religious belief and its moral implications.", claim: "Craig offers a cumulative case involving the universe, morality and Jesus. Hitchens challenges the case for theism and the character and effects of religion.", hinge: "Does an objection to the conduct or desirability of religion address the argument for God's existence, and where does a philosophical case become specifically Christian?", prompts: ["Separate each claim from the evidence offered for it.", "Identify which premise an objection challenges.", "Ask what would remain if one argument failed."], studies: ["why-anything", "morality", "church-harm", "resurrection"] },
  { id: "craig-ally-resurrection", title: "Hoax or history?", speakers: "William Lane Craig · Shabir Ally", setting: "McGill University · February 2009", source: "craig-ally-resurrection", lens: "Resurrection & Islam", description: "Examine an actual exchange about Jesus' death, resurrection and the competing interpretations of the sources.", claim: "Craig defends the resurrection as the best explanation of the evidence. Ally disputes that inference and discusses an alternative account of Jesus' fate.", hinge: "Which points are claims about the sources, which are historical inferences, and which depend on theological expectations?", prompts: ["Read both opening contributions before judging the replies.", "Track the difference between crucifixion, death and resurrection.", "Test the explanatory costs of each proposed account."], studies: ["resurrection", "islam-cross", "miracles", "contradictions"] },
  { id: "craig-ally-god", title: "The concept of God", speakers: "William Lane Craig · Shabir Ally", setting: "McMaster University · March 2002", source: "craig-ally-god", lens: "Trinity & tawhid", description: "Follow a Christian–Muslim exchange about God's unity, nature and character.", claim: "The speakers defend different accounts of God and challenge the other's account. The exchange includes arguments about divine unity and love.", hinge: "Does the criticism address what the other speaker actually affirms, or a definition the speaker rejects?", prompts: ["Write down each definition before evaluating it.", "Distinguish an objection to coherence from an objection to scriptural support.", "Compare the religious passages in their own contexts."], studies: ["god", "islam-trinity", "islam-jesus", "conversation"] },
];
export const PRACTICE = [
  { id: "grief", title: "“Where was God when I needed him?”", context: "A friend is speaking about a painful loss, not asking for a formal debate.", question: "What would you say first?", options: ["There must be a reason this happened.", "I'm sorry. Would you like to tell me what happened?", "Let me explain the free-will defence."], best: 1, explanation: "Start by making room for the person. A philosophical question may come later; it should not be forced onto a moment of grief. You do not need to claim knowledge of a hidden purpose.", study: "suffering", prompt: "Write a response that offers presence without pretending to explain the loss." },
  { id: "three-gods", title: "“You Christians believe in three gods.”", context: "A Muslim neighbour raises a concern about the Trinity.", question: "Which response first clarifies the disagreement?", options: ["Christians confess one God. Can I explain what we mean by persons and being?", "It is exactly like water, ice and steam.", "You would understand if you read the Bible."], best: 0, explanation: "State the actual Christian claim and invite clarification. An analogy may obscure the doctrine, while a dismissive reply avoids the question. Understanding the claim does not require your neighbour to accept it.", study: "islam-trinity", prompt: "Explain the Christian claim in two sentences, then ask a question that invites a reply." },
  { id: "changed-bible", title: "“The Bible has been rewritten so many times.”", context: "A colleague has heard that no original meaning can be recovered.", question: "Which question helps you investigate together?", options: ["There are no differences between any manuscripts.", "Every other ancient text is worse.", "Is there a particular passage or manuscript claim we could look at?"], best: 2, explanation: "Make the claim specific and open the evidence. Different translations, copying variants and the history of the canon are different issues. Ask which one your colleague means.", study: "manuscripts", prompt: "Draft one clarifying question and one source you could examine together." },
];
export const studyById = (id: string) => STUDIES.find((study) => study.id === id);
export const sourceById = (id: string) => SOURCES.find((source) => source.id === id)!;
export const topicById = (id: string) => TOPICS.find((topic) => topic.id === id);
export const studyMinutes = (study: ApStudy) => Math.max(2, Math.ceil([study.answer, ...study.reasoning, study.conclusion, ...study.sections.map((section) => section.body), study.reply, study.limit].join(" ").split(/\s+/).length / 180));
